diff --git a/ArmPkg/Library/ArmTrngLib/ArmTrngLib.c b/ArmPkg/Library/ArmTrngLib/ArmTrngLib.c
index c2555f3..dbcebca 100644
--- a/ArmPkg/Library/ArmTrngLib/ArmTrngLib.c
+++ b/ArmPkg/Library/ArmTrngLib/ArmTrngLib.c
@@ -324,6 +324,7 @@ ArmTrngLibConstructor (
   UINT16            MajorRev;
   UINT16            MinorRev;
   GUID              Guid;
+  UINTN             T81Stage = 0;
 
   ZeroMem (&Parameters, sizeof (Parameters));
 
@@ -340,18 +341,21 @@ ArmTrngLibConstructor (
     goto ErrorHandler;
   }
 
+  T81Stage = 1;
   Status = GetArmTrngVersion (&MajorRev, &MinorRev);
   if (RETURN_ERROR (Status)) {
     goto ErrorHandler;
   }
 
   // Check that the required features are present.
+  T81Stage = 2;
   Status = GetArmTrngFeatures (ARM_SMC_ID_TRNG_RND, NULL);
   if (RETURN_ERROR (Status)) {
     goto ErrorHandler;
   }
 
   // Check if TRNG UUID is supported and if so trace the GUID.
+  T81Stage = 3;
   Status = GetArmTrngFeatures (ARM_SMC_ID_TRNG_GET_UUID, NULL);
   if (RETURN_ERROR (Status)) {
     goto ErrorHandler;
@@ -359,6 +363,7 @@ ArmTrngLibConstructor (
 
   DEBUG_CODE_BEGIN ();
 
+  T81Stage = 4;
   Status = GetArmTrngUuid (&Guid);
   if (RETURN_ERROR (Status)) {
     goto ErrorHandler;
@@ -377,6 +382,7 @@ ArmTrngLibConstructor (
   return RETURN_SUCCESS;
 
 ErrorHandler:
+  DEBUG ((DEBUG_ERROR, "T81TRNG stage=%u smccc=0x%Lx status=0x%Lx\n", T81Stage, (UINT64)Parameters.Arg0, (UINT64)Status));
   DEBUG ((DEBUG_ERROR, "ArmTrngLib could not be correctly initialized.\n"));
   return RETURN_SUCCESS;
 }
