+    DEBUG ((DEBUG_ERROR, "T81DIAG pdb=%a status=0x%Lx\n", Image->ImageContext.PdbPointer != NULL ? Image->ImageContext.PdbPointer : "(none)", (UINT64)Image->Status));
 
